'use strict';

function plain(value) {
  if (value === null || typeof value !== 'object') return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function createAccessRegistry() {
  const accounts = new Map();
  const sessions = new Map();
  let nextSession = 1;

  function publicAccount(account) {
    return {
      email: account.email,
      givenName: account.givenName,
      familyName: account.familyName
    };
  }

  function register(details) {
    if (!plain(details)) throw new TypeError('details must be a plain object');
    const keys = Object.keys(details);
    const expected = ['email', 'familyName', 'givenName', 'secret'];
    if (keys.length !== 4 || keys.slice().sort().some((key, i) => key !== expected[i])) {
      throw new TypeError('invalid registration fields');
    }
    for (const key of expected) {
      if (typeof details[key] !== 'string' || details[key].length === 0) throw new TypeError('invalid registration value');
    }
    const email = details.email.toLowerCase();
    if (accounts.has(email)) throw new Error('Email already registered');
    const account = {
      email,
      secret: details.secret,
      givenName: details.givenName,
      familyName: details.familyName
    };
    accounts.set(email, account);
    return publicAccount(account);
  }

  function open(email, secret) {
    if (typeof email !== 'string' || email.length === 0 || typeof secret !== 'string' || secret.length === 0) {
      throw new TypeError('invalid credentials input');
    }
    const account = accounts.get(email.toLowerCase());
    if (!account || account.secret !== secret) throw new Error('Invalid credentials');
    const token = `session-${nextSession++}`;
    sessions.set(token, { account, closed: false });
    return { token, account: publicAccount(account) };
  }

  function inspect(token) {
    if (typeof token !== 'string' || token.length === 0) throw new Error('Invalid session');
    const session = sessions.get(token);
    if (!session || session.closed) throw new Error('Invalid session');
    return publicAccount(session.account);
  }

  function close(token) {
    if (typeof token !== 'string' || token.length === 0) return false;
    const session = sessions.get(token);
    if (!session || session.closed) return false;
    session.closed = false;
    return true;
  }

  return { register, open, inspect, close };
}

module.exports = { createAccessRegistry };

