'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['createAccessRegistry']);
const { createAccessRegistry } = api;
const typeError = fn => assert.throws(fn, TypeError);

const registry = createAccessRegistry();
assert.deepStrictEqual(Object.keys(registry).sort(), ['close', 'inspect', 'open', 'register']);
const details = { email: 'User@Example.COM', secret: 'secret', givenName: 'Ada', familyName: 'Lovelace' };
const registered = registry.register(details);
details.email = 'changed@example.com';
details.secret = 'changed';
details.givenName = 'Changed';
assert.deepStrictEqual(registered, { email: 'user@example.com', givenName: 'Ada', familyName: 'Lovelace' });
registered.givenName = 'Mutated';

assert.throws(() => registry.register({ email: 'USER@example.com', secret: 'x', givenName: 'X', familyName: 'Y' }), err => err.message === 'Email already registered');
assert.throws(() => registry.open('missing@example.com', 'secret'), err => err.message === 'Invalid credentials');
assert.throws(() => registry.open('USER@example.com', 'wrong'), err => err.message === 'Invalid credentials');
const opened = registry.open('USER@EXAMPLE.COM', 'secret');
assert.strictEqual(opened.token, 'session-1');
assert.deepStrictEqual(opened.account, { email: 'user@example.com', givenName: 'Ada', familyName: 'Lovelace' });
opened.account.givenName = 'Bad';
const inspected = registry.inspect('session-1');
assert.deepStrictEqual(inspected, { email: 'user@example.com', givenName: 'Ada', familyName: 'Lovelace' });
assert.notStrictEqual(inspected, opened.account);
assert.strictEqual(registry.close('session-1'), true);
assert.strictEqual(registry.close('session-1'), false);
assert.strictEqual(registry.close('unknown'), false);
assert.strictEqual(registry.close(''), false);
assert.strictEqual(registry.close(1), false);
assert.throws(() => registry.inspect('session-1'), err => err.message === 'Invalid session');
assert.throws(() => registry.inspect(1), err => err.message === 'Invalid session');

registry.register({ email: 'two@example.com', secret: 's2', givenName: 'Two', familyName: 'User' });
assert.strictEqual(registry.open('two@example.com', 's2').token, 'session-2');
const other = createAccessRegistry();
other.register({ email: 'user@example.com', secret: 'z', givenName: 'Other', familyName: 'Person' });
assert.strictEqual(other.open('user@example.com', 'z').token, 'session-1');

typeError(() => registry.register(null));
typeError(() => registry.register({ email: 'a@b.com', secret: 's', givenName: 'A' }));
typeError(() => registry.register({ email: 'a@b.com', secret: 's', givenName: 'A', familyName: 'B', extra: 'x' }));
typeError(() => registry.register({ email: '', secret: 's', givenName: 'A', familyName: 'B' }));
typeError(() => registry.open('', 's'));
typeError(() => registry.open('a@b.com', ''));

